export const shareSplitDefinitions={shareSplit:{title:'Follow one holding through a proportional share split and a later price',fields:[
  ['splitOldShares','Shares held before the split',121,1,1000000,1],
  ['splitOldPrice','Price per old share before the split (CAD)',90,.01,10000,1],
  ['splitNewUnits','New shares in the split ratio',3,1,20,1],
  ['splitOldUnits','Old shares in the split ratio',2,1,20,1],
  ['splitLaterPrice','Later price per new share (CAD)',55,0,200000,1]
]}};
export function shareSplitLedger(input){
  const ratio=input.splitNewUnits/input.splitOldUnits,newShares=input.splitOldShares*ratio,adjustedPrice=input.splitOldPrice/ratio;
  const before=input.splitOldShares*input.splitOldPrice,mechanical=newShares*adjustedPrice,later=newShares*input.splitLaterPrice;
  return {ratio,newShares,adjustedPrice,before,mechanical,later,change:later-before,rawPriceReturn:input.splitLaterPrice/input.splitOldPrice-1,holdingReturn:later/before-1};
}
export function shareSplitResult(kind,input){
  if(kind!=='shareSplit')throw Error('Unknown share-split topic.');
  const p=shareSplitLedger(input);
  return {metrics:[['Mathematical new-share entitlement, before any fractional-share treatment',p.newShares,'shares'],['Later value of the full mathematical entitlement',p.later,'money'],['Holding return with the split correctly reflected',p.holdingReturn,'percent']],note:'Original CAD example of a proportional stock split or reverse split, followed by a separately selected later market price. New shares per old share equal the entered new-unit count divided by the old-unit count. The mechanical reference price moves inversely, preserving the holding value at the split itself. Full fractional entitlement is retained mathematically; no issuer or broker cash-in-lieu, rounding, fee, payment date, dividend, tax or account treatment is modeled. Quantity displays round to at most six decimals; calculations retain the full precision. No ticker, live price, split announcement or expected return is used.',charts:[
    {id:'share-split-quantities',type:'bar',title:'The share count changes with the ratio; it is not an investment return',unit:'shares',unitLabel:'Shares · full mathematical entitlement, displayed to six decimals at most',rows:[{label:'Old shares before the split',value:input.splitOldShares},{label:'New-share entitlement after the split',value:p.newShares}],note:`The chosen ratio is ${input.splitNewUnits} new shares for ${input.splitOldUnits} old shares. Quantities can include a fractional entitlement. This chart does not round that entitlement down, promise that a broker will retain it or create a cash payment for it. A smaller share count in a reverse split can coexist with an unchanged mechanical holding value.`},
    {id:'share-split-price-basis',type:'line',title:'Put the earlier price on the new-share basis before reading a return',unit:'money',unitLabel:'CAD per share · old basis or new basis as labelled',xLabel:'Illustrative comparison point',xTicks:[{value:0,label:'Before'},{value:1,label:'Split'},{value:2,label:'Later'}],series:[{name:'Unadjusted quote: old basis before, new basis after',dash:true,rows:[{x:0,value:input.splitOldPrice},{x:1,value:p.adjustedPrice},{x:2,value:input.splitLaterPrice}]},{name:'Comparable new-share basis at all three points',rows:[{x:0,value:p.adjustedPrice},{x:1,value:p.adjustedPrice},{x:2,value:input.splitLaterPrice}]}],note:'The reference immediately after the split assumes only the proportional mechanical adjustment. The later price is an independent input. Lines join three teaching points and do not reconstruct actual trading. The adjusted earlier price is a comparison unit, not a claim that old shares historically traded at that amount. Only this split is adjusted; no dividend or other corporate action is included.'},
    {id:'share-split-return-comparison',type:'signedbar',title:'An unadjusted price comparison can give the wrong impression of the holding return',unit:'percent',unitLabel:'Percentage change · no dividends, tax or fees',rows:[{label:'Later quote / old-share quote − 1: mismatched units',value:p.rawPriceReturn},{label:'Later holding value / original holding value − 1',value:p.holdingReturn}],note:'The first percentage divides prices for different share units when the ratio differs from one. It is shown as a diagnostic, not as the investor return. With the full entitlement retained, the correct second percentage also equals later new-share price divided by split-adjusted earlier price, minus one.'},
    {id:'share-split-value-bridge',type:'waterfall',title:'Separate the zero mechanical value change from the later market-price change',unit:'money',rows:[{label:'Original holding value before the split',value:p.before},{label:'Value added by proportional split alone',value:0},{label:'Subsequent market-price change on all new shares',value:p.change}],totalLabel:'Later holding value',note:'The split adds zero value under the proportional reference assumption. Later price movement changes the value of the complete new-share entitlement. This is an unrealized valuation bridge, not a bank-cash receipt, contribution, dividend or sale settlement.'},
    {id:'share-split-raw-quote-matrix',type:'heatmap',title:'Different split ratios can disguise the same underlying holding return',unit:'percent',signed:true,unitLabel:'Raw later quote / original old-share quote − 1 · deliberately unadjusted',columns:['−20%','0%','+20%','+50%'],rows:[[1,2],[1,1],[3,2],[2,1]].map(([newUnits,oldUnits])=>({label:newUnits+':'+oldUnits,values:[-.2,0,.2,.5].map(returnValue=>(1+returnValue)/(newUnits/oldUnits)-1)})),note:'Rows replace the split ratio, written new shares : old shares. Columns replace the true holding return after the split. Cells show the misleading unadjusted quote change, not the holding return named in the column. For example, a two-for-one split and a 20% holding gain still give a 40% fall when the new quote is divided by the old quote. The grid replaces both the selected ratio and later price, and has no market probabilities.'}
  ]};
}
